-- MySQL格式的建表语句
DROP TABLE IF EXISTS `client`;

CREATE TABLE `client` (
  `cli_name` VARCHAR(100) DEFAULT NULL COMMENT '客户名称',
  `cli_degree` VARCHAR(200) DEFAULT '1' COMMENT '客户等级；1表示普通客户；2表示重点客户',
  `cli_type` VARCHAR(500) DEFAULT NULL COMMENT '客户类型',
  `cli_state` VARCHAR(200) DEFAULT NULL COMMENT '状态',
  `cli_contact` VARCHAR(200) DEFAULT NULL COMMENT '联系人',
  `cli_phone` VARCHAR(500) DEFAULT NULL COMMENT '联系电话',
  `cli_lat` VARCHAR(100) DEFAULT NULL COMMENT '纬度',
  `cli_lon` VARCHAR(100) DEFAULT NULL COMMENT '经度',
  `cli_province` VARCHAR(50) DEFAULT NULL COMMENT '省',
  `cli_city` VARCHAR(100) DEFAULT NULL COMMENT '市',
  `cli_area` VARCHAR(200) DEFAULT NULL COMMENT '采用编码，通过查询"区域信息表"',
  `cli_street` VARCHAR(500) DEFAULT NULL COMMENT '街道',
  `remarks` VARCHAR(200) DEFAULT NULL COMMENT '备注',
  `editor` VARCHAR(100) DEFAULT NULL COMMENT '编辑人',
  `edtime` DATETIME DEFAULT NULL COMMENT '编辑时间',
  `clientid` BIGINT DEFAULT NULL COMMENT '客户编码',
  PRIMARY KEY (`clientid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='客户信息表';

